var n=`0882-thukpa`;var t=`world-0882`;var a=`NP`;var s=`south-asia`;var o=4;var r=55;var g={en:`Thukpa`,ua:`Тукпа`};var l={en:`Thukpa is a Nepal dish made with yellow onion, garlic, chicken thigh, carrot. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Тукпа, страва кухні країни Непал. Основні складники: жовта цибуля, часник, куряче стегно, морква. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,180,`g`],[`garlic`,4,`clove`],[`ground-ginger`,20,`g`],[`canola-oil`,34,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 32 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 32 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:32,i:[[`chicken-thigh`,480,`g`],[`carrot`,210,`g`],[`white-cabbage`,190,`g`],[`chicken-stock`,1100,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`wheat-noodles`,290,`g`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`cilantro`,20,`g`],[`light-soy-sauce`,30,`ml`]]}];var d={slug:n,id:t,country:`NP`,region:s,servings:4,minutes:55,title:g,text:l,steps:h};export{a as country,d as default,t as id,r as minutes,s as region,o as servings,n as slug,h as steps,l as text,g as title};